import SwiftUI
import UIKit

/// El mark de Amadai (version blanca), embebido directo como datos en vez
/// de vivir en el asset catalog. Se hizo asi porque, pese a varias
/// vueltas (limpiar DerivedData, agregar ASSETCATALOG_COMPILER_*,
/// verificar el PNG y el Contents.json byte por byte), el catalogo de
/// assets de este proyecto nunca logro resolver "AlzaMarkWhite" en
/// tiempo de ejecucion (UIImage(named:) siempre regresaba nil) sin que
/// se pudiera confirmar la causa exacta (no hay forma de sacar el log
/// de actool desde este entorno). Esto rodea el problema por completo:
/// el PNG original viaja como base64 dentro del binario compilado, asi
/// que no depende en nada de como Xcode compile Assets.xcassets.
enum EmbeddedLogo {
    static var alzaMarkWhite: Image {
        guard
            let data = Data(base64Encoded: base64WhitePNG, options: .ignoreUnknownCharacters),
            let uiImage = UIImage(data: data)
        else {
            return Image(systemName: "a.circle.fill")
        }
        return Image(uiImage: uiImage)
    }

